"""Register extracted routes without changing legacy Flask endpoint names."""
from . import main, api, auth, admin, admin_schedule, fantasy, draft, profile, minigames, schedule

def register_routes(app, schedule_dependencies=None):
    if schedule_dependencies is None:
        raise ValueError("Schedule dependencies must be provided")
    admin_schedule.configure(schedule_dependencies)
    fantasy.configure(schedule_dependencies)
    profile.configure(schedule_dependencies)
    draft.configure({"unlock_draft_achievements": schedule_dependencies["unlock_draft_achievements"], "DRAFT_ACHIEVEMENTS": schedule_dependencies["DRAFT_ACHIEVEMENTS"]})
    app.add_url_rule('/draft', endpoint='draft_mode', view_func=draft.draft_mode)
    app.add_url_rule('/api/draft/pool', endpoint='draft_pool', view_func=draft.draft_pool)
    app.add_url_rule('/api/draft/simulate', endpoint='simulate_draft_api', view_func=draft.simulate_draft_api, methods=['POST'])
    app.add_url_rule('/api/draft/my-stats', endpoint='my_draft_stats', view_func=draft.my_draft_stats, methods=['GET'])
    app.add_url_rule('/api/profile/account', endpoint='update_profile_account', view_func=profile.update_profile_account, methods=['POST'])
    app.add_url_rule('/api/profile/favorite-team', endpoint='profile_favorite_team', view_func=profile.profile_favorite_team, methods=['GET', 'POST'])
    app.add_url_rule('/api/games/basketball-grid/profile', endpoint='basketball_grid_profile', view_func=profile.basketball_grid_profile, methods=['GET'])
    app.add_url_rule('/api/profile/titles', endpoint='profile_titles', view_func=profile.profile_titles, methods=['GET'])
    app.add_url_rule('/api/profile/titles/equip', endpoint='equip_profile_title', view_func=profile.equip_profile_title, methods=['POST'])
    # Phase 11.7: public schedule and minigames (legacy endpoints preserved).
    app.add_url_rule('/other-games', endpoint='other_games', view_func=minigames.other_games)
    app.add_url_rule('/games/higher-or-lower', endpoint='higher_or_lower', view_func=minigames.higher_or_lower)
    app.add_url_rule('/api/games/higher-or-lower/start', endpoint='hl_start', view_func=minigames.hl_start, methods=['POST'])
    app.add_url_rule('/api/games/higher-or-lower/guess', endpoint='hl_guess', view_func=minigames.hl_guess, methods=['POST'])
    app.add_url_rule('/api/games/higher-or-lower/my-stats', endpoint='hl_my_stats', view_func=minigames.hl_my_stats, methods=['GET'])
    app.add_url_rule('/schedule', endpoint='schedule', view_func=schedule.schedule)
    app.add_url_rule('/api/schedule/<int:week_number>', endpoint='api_schedule', view_func=schedule.api_schedule)
    # Fantasy endpoints retain the exact legacy names and URL paths.
    app.add_url_rule('/fantasy', endpoint='fantasy', view_func=fantasy.fantasy)
    app.add_url_rule('/fantasy/save', endpoint='fantasy_save', view_func=fantasy.fantasy_save, methods=['POST'])
    app.add_url_rule('/fantasy/lineup', endpoint='fantasy_lineup', view_func=fantasy.fantasy_lineup)
    app.add_url_rule('/fantasy/lineup/save', endpoint='fantasy_lineup_save', view_func=fantasy.fantasy_lineup_save, methods=['POST'])
    app.add_url_rule('/fantasy/dashboard', endpoint='fantasy_dashboard', view_func=fantasy.fantasy_dashboard)
    app.add_url_rule('/', endpoint='home', view_func=main.home)
    app.add_url_rule('/players', endpoint='player_directory', view_func=main.player_directory)
    app.add_url_rule('/teams', endpoint='team_directory', view_func=main.team_directory)
    app.add_url_rule('/teams/<int:team_id>', endpoint='team_profile', view_func=main.team_profile)
    app.add_url_rule('/profile', endpoint='profile', view_func=main.profile)
    app.add_url_rule('/api/players', endpoint='get_players', view_func=api.get_players)
    app.add_url_rule('/api/legends', endpoint='get_legends', view_func=api.get_legends, methods=['GET'])
    app.add_url_rule('/api/teams', endpoint='get_teams', view_func=api.get_teams)
    app.add_url_rule('/register', endpoint='register', view_func=auth.register, methods=['GET', 'POST'])
    app.add_url_rule('/login', endpoint='login', view_func=auth.login, methods=['GET', 'POST'])
    app.add_url_rule('/logout', endpoint='logout', view_func=auth.logout, methods=['POST'])
    app.add_url_rule('/admin', endpoint='admin_dashboard', view_func=admin.admin_dashboard, methods=['GET'])
    app.add_url_rule('/admin/players', endpoint='admin_players', view_func=admin.admin_players, methods=['GET'])
    app.add_url_rule('/admin/players/add', endpoint='admin_add_player', view_func=admin.admin_add_player, methods=['GET', 'POST'])
    app.add_url_rule('/admin/players/<int:player_id>/edit', endpoint='admin_edit_player', view_func=admin.admin_edit_player, methods=['GET', 'POST'])
    app.add_url_rule('/admin/players/<int:player_id>/delete', endpoint='admin_delete_player', view_func=admin.admin_delete_player, methods=['POST'])
    app.add_url_rule('/admin/teams', endpoint='admin_teams', view_func=admin.admin_teams, methods=['GET'])
    app.add_url_rule('/admin/teams/add', endpoint='admin_add_team', view_func=admin.admin_add_team, methods=['GET', 'POST'])
    app.add_url_rule('/admin/teams/<int:team_id>/edit', endpoint='admin_edit_team', view_func=admin.admin_edit_team, methods=['GET', 'POST'])
    app.add_url_rule('/admin/teams/<int:team_id>/delete', endpoint='admin_delete_team', view_func=admin.admin_delete_team, methods=['POST'])
    app.add_url_rule('/admin/legends', endpoint='admin_legends', view_func=admin.admin_legends, methods=['GET'])
    app.add_url_rule('/admin/legends/add', endpoint='admin_add_legend', view_func=admin.admin_add_legend, methods=['GET', 'POST'])
    app.add_url_rule('/admin/legends/<int:legend_id>/edit', endpoint='admin_edit_legend', view_func=admin.admin_edit_legend, methods=['GET', 'POST'])
    app.add_url_rule('/admin/legends/<int:legend_id>/delete', endpoint='admin_delete_legend', view_func=admin.admin_delete_legend, methods=['POST'])
    app.add_url_rule('/admin/users', endpoint='admin_users', view_func=admin.admin_users, methods=['GET'])
    app.add_url_rule('/admin/users/<int:user_id>/edit', endpoint='admin_edit_user', view_func=admin.admin_edit_user, methods=['GET', 'POST'])
    app.add_url_rule('/admin/users/<int:user_id>/delete', endpoint='admin_delete_user', view_func=admin.admin_delete_user, methods=['POST'])
    app.add_url_rule('/admin/schedule', endpoint='admin_schedule', view_func=admin_schedule.admin_schedule, methods=['GET'])
    app.add_url_rule('/admin/schedule/lock', endpoint='admin_schedule_lock', view_func=admin_schedule.admin_schedule_lock, methods=['POST'])
    app.add_url_rule('/admin/schedule/simulate', endpoint='admin_schedule_simulate', view_func=admin_schedule.admin_schedule_simulate, methods=['POST'])
    app.add_url_rule('/admin/schedule/review', endpoint='admin_schedule_review', view_func=admin_schedule.admin_schedule_review, methods=['GET'])
    app.add_url_rule('/admin/schedule/review/player/<int:stat_id>', endpoint='admin_schedule_edit_player', view_func=admin_schedule.admin_schedule_edit_player, methods=['POST'])
    app.add_url_rule('/admin/schedule/finalize', endpoint='admin_schedule_finalize', view_func=admin_schedule.admin_schedule_finalize, methods=['POST'])
    app.add_url_rule('/admin/schedule/next', endpoint='admin_schedule_next', view_func=admin_schedule.admin_schedule_next, methods=['POST'])
    app.add_url_rule('/admin/schedule/reset-round', endpoint='admin_schedule_reset_round', view_func=admin_schedule.admin_schedule_reset_round, methods=['POST'])
    app.add_url_rule('/admin/schedule/reset-season', endpoint='admin_schedule_reset_season', view_func=admin_schedule.admin_schedule_reset_season, methods=['POST'])
